const message = String($json.chatInput ?? '').trim();
const lower = message.toLowerCase();

let route = 'collector';

if (/\b(cancel|cancellation|cancelled|remove my appointment)\b/.test(lower)) {
  route = 'cancellation';
} else if (/\b(book|booking|schedule|appointment|reserve|confirm my appointment)\b/.test(lower)) {
  route = 'booking';
}

let roleInstructions = '';

if (route === 'booking') {
  roleInstructions = `ROLE: BOOKING AGENT
Help the user complete a doctor appointment booking request.

Required fields:
1. patient name
2. phone number
3. hospital
4. doctor
5. appointment date
6. appointment time

Use conversation history to reuse information already provided.
Ask only for missing information.

PHASE 2:
A local doctor database is provided.
Use it as the source of truth for availability.

If the requested doctor, hospital, date and time exist and available is Yes, tell the user that the slot is currently available.
If available is No, tell the user that the slot is not available.
If the requested slot does not exist, say that it was not found in the current database.

Do not claim that the appointment has actually been booked.`;
} else if (route === 'cancellation') {
  roleInstructions = `ROLE: CANCELLATION AGENT
Help the user cancel an existing doctor appointment.

Collect:
- patient name
- phone number
- hospital
- doctor
- appointment date
- appointment time

Use conversation history when available.

The current phase only collects cancellation details.
Do not claim that a real appointment has been cancelled.`;
} else {
  roleInstructions = `ROLE: COLLECTOR AGENT
Understand whether the user wants to book or cancel an appointment.

For booking collect:
- patient name
- phone number
- hospital
- doctor
- appointment date
- appointment time

For cancellation collect the same details.

Do not ask again for information already present in the conversation history.
If the intention is unclear, ask whether the user wants to book or cancel.`;
}

return [{
  json: {
    ...$json,
    route,
    roleInstructions
  }
}];
